static void merge(int* a, int* buf, size_t left, size_t mid, size_t right) {
    size_t i = left, j = mid, k = left;
    while (i < mid && j < right) {
        if (a[i] <= a[j])
            buf[k++] = a[i++];
        else
            buf[k++] = a[j++];
    }
    while (i < mid)
        buf[k++] = a[i++];
    while (j < right)
        buf[k++] = a[j++];
    for (size_t p = left; p < right; ++p)
